fn frame(t: i32) {
    host::display::clear(0x0d0f12);
    let mut phase: i32 = host::display::state_get(0);
    if phase == 0 {
        if host::display::state_get(2) >= 5 {
            host::display::state_set(0, 4);
        } else {
            host::display::state_set(2, host::display::state_get(2) + 1);
            let h: i32 = host::http::get("https://example.com/", 20);
            host::display::state_set(1, h);
            if h < 0 {
                host::display::state_set(0, 3);
                host::display::state_set(3, 180);
            } else {
                host::display::state_set(0, 1);
            }
        }
        phase = host::display::state_get(0);
    }
    if phase == 1 {
        let h2: i32 = host::display::state_get(1);
        let r: i32 = host::http::ready(h2);
        if r == 1 {
            host::display::state_set(0, 2);
        } else if r < 0 {
            host::display::state_set(0, 3);
            host::display::state_set(3, 180);
        }
        phase = host::display::state_get(0);
    }
    if phase == 3 {
        let wait: i32 = host::display::state_get(3);
        if wait > 0 {
            host::display::state_set(3, wait - 1);
        } else {
            host::display::state_set(0, 0);
        }
    }
    host::display::draw_string(120, 50, "STUBBORN FETCH", 0xffffff, 2);
    host::display::draw_string(120, 100, "ATTEMPT", 0x888888, 1);
    host::display::draw_number(190, 98, host::display::state_get(2), 0xffffff, 1);
    host::display::draw_string(214, 100, "OF 5", 0x888888, 1);
    if phase == 1 {
        host::display::draw_string(120, 200, "IN FLIGHT", 0xaa7700, 2);
    } else if phase == 2 {
        let h3: i32 = host::display::state_get(1);
        host::display::draw_string(120, 200, "GOT IT", 0x22bb44, 3);
        host::display::draw_string(120, 260, "STATUS", 0x888888, 1);
        host::display::draw_number(180, 258, host::http::status(h3), 0x66ddff, 1);
    } else if phase == 3 {
        host::display::draw_string(120, 200, "FAILED - RETRYING", 0xbb5533, 2);
        let wait2: i32 = host::display::state_get(3);
        host::display::fill_rect(120, 250, wait2, 10, 0xaa7700);
    } else if phase == 4 {
        host::display::draw_string(120, 200, "GAVE UP", 0xbb2222, 3);
        host::display::draw_string(120, 260, "5 ATTEMPTS BURNED", 0x777777, 1);
    }
    host::display::present();
}
